sampler sampler_pw_noise_lq;
vec2 uv0, uv1, uv2,uv4,rsk,dz1,Kugel1;;
const float sw1 =  (rand_preset.x) >= .4;
const float sw2 =  (rand_preset.y);

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  uv0 = uv;
uv2 = vec2(.2/rad+uTime / 4.0,ang/3.14) * 2.0;
float mod = length(sin(uv2*3.141/2+uTime*.1));
vec2 noise = texture(sampler_noise_hq,uv2+mod).rg;
float mask = (noise.r <= sw2);
vec2 rohr = sw1*rad * (noise-.5) / 2.0*mask;
uv1 = vec2(1.0 - uv.x,uv.y);
ret =  GetPixel(uv)+GetPixel(uv1).xy;
vec3 back = .2*(.5+(uv.x-.5)*q1+(uv.y-.5)*q2);
uv+= rohr * sw1;
uv1 = vec2(1.0 - uv.x,uv.y);
ret += (GetBlur2(uv) + GetBlur2(uv1).xy) *min(.5+audioHighSmooth / 4.0, 2.0 ) *(1.0 + sw1) * clamp01(1.0 - lum(ret) / 2.0);
ret += (sw1 == 0.0 ? 1.0 : 0.0)*back;
ret = mix(ret*(hue_shader * 2.0-1),ret,lum(ret));;
//ret = GetPixel(uv);
  fragColor = vec4(ret, 1.0);
}

